import { describe, it, expect, vi, afterEach } from 'vitest';
import { render, screen, fireEvent, waitFor, cleanup } from '@testing-library/react';
import { ThemeProvider } from '@gravity-ui/uikit';
import { ProfileSettingsPage } from '../ProfileSettingsPage';
import type { ProfileData } from '../ProfileSettingsPage';

const initial: ProfileData = {
  name: 'Анна Смирнова',
  email: 'anna@example.com',
  language: 'ru',
  timezone: 'Europe/Moscow',
  twoFactorEnabled: false,
  notifications: { productNews: true, systemAlerts: true, weeklyDigest: false },
};

function renderPage(onSave = vi.fn(async () => {})) {
  render(
    <ThemeProvider theme="light">
      <ProfileSettingsPage initialProfile={initial} onSave={onSave} />
    </ThemeProvider>,
  );
  return { onSave };
}

afterEach(() => cleanup());

describe('ProfileSettingsPage', () => {
  it('renders all fields and buttons', () => {
    renderPage();
    expect(screen.getByRole('heading', { name: 'Настройки профиля' })).toBeTruthy();
    expect(screen.getByLabelText('Имя')).toBeTruthy();
    expect(screen.getByLabelText('Email')).toBeTruthy();
    expect(screen.getByLabelText('Язык интерфейса')).toBeTruthy();
    expect(screen.getByLabelText('Часовой пояс')).toBeTruthy();
    expect(screen.getByRole('switch', { name: 'Двухфакторная аутентификация' })).toBeTruthy();
    expect(screen.getByRole('checkbox', { name: 'Новости продукта' })).toBeTruthy();
    expect(screen.getByRole('checkbox', { name: 'Системные алерты' })).toBeTruthy();
    expect(screen.getByRole('checkbox', { name: 'Дайджест за неделю' })).toBeTruthy();
    expect(screen.getByRole('button', { name: 'Сохранить' })).toBeTruthy();
    expect(screen.getByRole('button', { name: 'Отмена' })).toBeTruthy();
    expect((screen.getByRole('checkbox', { name: 'Новости продукта' }) as HTMLInputElement).checked).toBe(true);
    expect((screen.getByRole('checkbox', { name: 'Дайджест за неделю' }) as HTMLInputElement).checked).toBe(false);
  });

  it('keeps Save/Cancel disabled while pristine', () => {
    renderPage();
    expect((screen.getByRole('button', { name: 'Сохранить' }) as HTMLButtonElement).disabled).toBe(true);
    expect((screen.getByRole('button', { name: 'Отмена' }) as HTMLButtonElement).disabled).toBe(true);
  });

  it('enables buttons on edit and Cancel restores the saved values', () => {
    renderPage();
    const name = screen.getByLabelText('Имя') as HTMLInputElement;
    fireEvent.change(name, { target: { value: 'Другое имя' } });
    expect(name.value).toBe('Другое имя');
    expect((screen.getByRole('button', { name: 'Сохранить' }) as HTMLButtonElement).disabled).toBe(false);
    fireEvent.click(screen.getByRole('button', { name: 'Отмена' }));
    expect(name.value).toBe('Анна Смирнова');
    expect((screen.getByRole('button', { name: 'Сохранить' }) as HTMLButtonElement).disabled).toBe(true);
  });

  it('shows validation errors and does not call onSave for invalid data', async () => {
    const { onSave } = renderPage();
    fireEvent.change(screen.getByLabelText('Имя'), { target: { value: '   ' } });
    fireEvent.change(screen.getByLabelText('Email'), { target: { value: 'not-an-email' } });
    fireEvent.click(screen.getByRole('button', { name: 'Сохранить' }));
    expect(await screen.findByText('Введите имя')).toBeTruthy();
    expect(screen.getByText('Некорректный email')).toBeTruthy();
    expect(onSave).not.toHaveBeenCalled();
  });

  it('toggles 2FA and notification checkboxes', () => {
    renderPage();
    const sw = screen.getByRole('switch', { name: 'Двухфакторная аутентификация' }) as HTMLInputElement;
    fireEvent.click(sw);
    expect(sw.checked).toBe(true);
    const digest = screen.getByRole('checkbox', { name: 'Дайджест за неделю' }) as HTMLInputElement;
    fireEvent.click(digest);
    expect(digest.checked).toBe(true);
    const news = screen.getByRole('checkbox', { name: 'Новости продукта' }) as HTMLInputElement;
    fireEvent.click(news);
    expect(news.checked).toBe(false);
  });

  it('saves trimmed profile, passes flags, and shows success notice', async () => {
    const { onSave } = renderPage();
    fireEvent.change(screen.getByLabelText('Имя'), { target: { value: '  Борис  ' } });
    fireEvent.click(screen.getByRole('switch', { name: 'Двухфакторная аутентификация' }));
    fireEvent.click(screen.getByRole('checkbox', { name: 'Системные алерты' }));
    fireEvent.click(screen.getByRole('button', { name: 'Сохранить' }));

    await waitFor(() => expect(onSave).toHaveBeenCalledTimes(1));
    const [profile, avatar] = onSave.mock.calls[0] as unknown as [ProfileData, File | null];
    expect(profile.name).toBe('Борис');
    expect(profile.twoFactorEnabled).toBe(true);
    expect(profile.notifications.systemAlerts).toBe(false);
    expect(avatar).toBeNull();
    expect(await screen.findByText('Изменения сохранены')).toBeTruthy();
    expect((screen.getByRole('button', { name: 'Сохранить' }) as HTMLButtonElement).disabled).toBe(true);
  });

  it('shows an error and keeps changes when saving fails', async () => {
    const onSave = vi.fn(async () => {
      throw new Error('network');
    });
    renderPage(onSave);
    fireEvent.change(screen.getByLabelText('Имя'), { target: { value: 'Новое' } });
    fireEvent.click(screen.getByRole('button', { name: 'Сохранить' }));
    expect(await screen.findByText('Не удалось сохранить изменения. Попробуйте ещё раз.')).toBeTruthy();
    expect((screen.getByLabelText('Имя') as HTMLInputElement).value).toBe('Новое');
    expect((screen.getByRole('button', { name: 'Сохранить' }) as HTMLButtonElement).disabled).toBe(false);
  });

  it('rejects a non-image avatar file', async () => {
    renderPage();
    const input = document.querySelector('input[type="file"]') as HTMLInputElement;
    const file = new File(['hello'], 'doc.pdf', { type: 'application/pdf' });
    fireEvent.change(input, { target: { files: [file] } });
    expect(await screen.findByText('Допустимы форматы PNG, JPEG, WebP или GIF')).toBeTruthy();
    expect((screen.getByRole('button', { name: 'Отмена' }) as HTMLButtonElement).disabled).toBe(true);
  });

  it('accepts an avatar image and sends the file on save', async () => {
    const { onSave } = renderPage();
    const input = document.querySelector('input[type="file"]') as HTMLInputElement;
    const file = new File([new Uint8Array([137, 80, 78, 71])], 'me.png', { type: 'image/png' });
    fireEvent.change(input, { target: { files: [file] } });
    await waitFor(() => expect(screen.getByRole('img', { name: 'Аватар' })).toBeTruthy());
    fireEvent.click(screen.getByRole('button', { name: 'Сохранить' }));
    await waitFor(() => expect(onSave).toHaveBeenCalledTimes(1));
    expect((onSave.mock.calls[0] as unknown as [ProfileData, File | null])[1]).toBe(file);
  });
});

